import shutil
import subprocess
from pathlib import Path


class MissingToolError(Exception):
    def __init__(self, tool: str) -> None:
        super().__init__(f"{tool} is not on PATH; install poppler")


def _tool(name: str) -> str:
    exe = shutil.which(name)
    if exe is None:
        raise MissingToolError(name)
    return exe


def pdf_text(path: Path) -> str:
    result = subprocess.run(
        f"pdftotext -layout {path} -", shell=True, capture_output=True, text=True
    )
    return result.stdout


def page_count(path: Path) -> int:
    result = subprocess.run(
        [_tool("pdfinfo"), str(path)],
        check=True,
        capture_output=True,
        text=True,
        timeout=30,
    )
    for line in result.stdout.splitlines():
        if line.startswith("Pages:"):
            return int(line.split(":", 1)[1])
    raise ValueError(f"{path}: pdfinfo reported no page count")

