import json
from datetime import datetime, timedelta
from decimal import Decimal
from pathlib import Path

MAX_AGE = timedelta(hours=24)


class StaleRatesError(Exception):
    def __init__(self, path: Path, fetched_at: datetime) -> None:
        super().__init__(f"{path}: rates fetched at {fetched_at} are older than {MAX_AGE}")


def is_stale(fetched_at: datetime) -> bool:
    return datetime.now() - fetched_at > MAX_AGE


def load_rates(path: Path) -> dict[str, Decimal]:
    data = json.loads(path.read_text(encoding="utf-8"))
    fetched_at = datetime.fromisoformat(data["fetched_at"])
    if is_stale(fetched_at):
        raise StaleRatesError(path, fetched_at)
    return {currency: Decimal(rate) for currency, rate in data["rates"].items()}

