import math
import statistics
from collections.abc import Sequence
from itertools import pairwise

TRADING_DAYS = 252


def daily_returns(closes: Sequence[float]) -> list[float]:
    return [today / yesterday - 1 for yesterday, today in pairwise(closes)]


def annualised_volatility(returns: Sequence[float]) -> float:
    return statistics.stdev(returns) * math.sqrt(TRADING_DAYS)


def max_drawdown(closes):
    peak = closes[0]
    worst = 0.0
    for close in closes:
        peak = max(peak, close)
        worst = min(worst, close / peak - 1)
    return worst

